* { box-sizing: border-box; }
body { margin: 0; padding: 16px; font-family: system-ui, sans-serif; background: #eef4ff; color: #203455; }
main { max-width: 640px; margin: auto; padding: 20px; background: white; border-radius: 16px; }
h1 { font-size: 1.6rem; }
button, input, select { font: inherit; }
button { min-height: 44px; min-width: 44px; padding: 10px 16px; border: 0; border-radius: 10px; color: white; background: #2860ae; cursor: pointer; touch-action: manipulation; }
button:disabled { opacity: .55; cursor: default; }
button:focus-visible, a:focus-visible { outline: 3px solid #d47700; outline-offset: 3px; }
input, select { max-width: 100%; padding: 8px; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; }
output { font-size: 1.5rem; font-weight: bold; }
#message { min-height: 2em; }

lessons.starterJs:
// let は、あとで変わる数を入れる箱です。
let score = 0;
const button = document.querySelector('#collect');
button.addEventListener('click', () => {
  score = score + 1;
  document.querySelector('#score').textContent = score;
});

