lessons.starterJs:
// 宝は箱2（番号1）です。番号は0から始まります。
const treasure = 1;
const boxes = document.querySelectorAll('[data-box]');
boxes.forEach((box) => {
  box.addEventListener('click', () => {
    const found = Number(box.dataset.box) === treasure;
    document.querySelector('#message').textContent = found ? '宝を発見！' : 'からっぽ。別の箱を選ぼう';
    if (found) {
      box.classList.add('found');
      boxes.forEach((item) => { item.disabled = true; });
    }
  });
});

