lessons.starterJs:
const names = ['グー', 'チョキ', 'パー'];
let wins = 0;
let rounds = 0;
function judge(player, computer) {
  if (player === computer) return 'あいこ';
  if ((player + 1) % 3 === computer) return '勝ち';
  return '負け';
}
function render(message) {
  document.querySelector('#score').textContent = wins;
  document.querySelector('#rounds').textContent = rounds;
  document.querySelector('#message').textContent = message;
}
document.querySelectorAll('[data-hand]').forEach((button) => {
  button.addEventListener('click', () => {
    const computer = Math.floor(Math.random() * 3);
    const result = judge(Number(button.dataset.hand), computer);
    rounds = rounds + 1;
    if (result === '勝ち') wins = wins + 1;
    render('相手：' + names[computer] + ' / ' + result);
  });
});
document.querySelector('#reset').addEventListener('click', () => { wins = 0; rounds = 0; render('手を選ぼう'); });

