const questions = [
  { text: '見出しのタグは？', choices: ['h1', 'p', 'img'], answer: 0 },
  { text: '見た目を整える技術は？', choices: ['HTML', 'CSS', 'JavaScript'], answer: 1 },
  { text: 'クリックなどの動作を付ける技術は？', choices: ['HTML', 'CSS', 'JavaScript'], answer: 2 }
];
let index = 0;
let score = 0;
function render() {
  const item = questions[index];
  document.querySelector('#question').textContent = (index + 1) + '. ' + item.text;
  document.querySelector('#choices').replaceChildren();
  document.querySelector('#message').textContent = '答えを選ぼう';
  document.querySelector('#next').disabled = true;
  item.choices.forEach((choice, number) => {
    const button = document.createElement('button');
    button.type = 'button'; button.textContent = choice;
    button.addEventListener('click', () => {
      if (number === item.answer) score = score + 1;
      document.querySelector('#score').textContent = score;
      document.querySelector('#message').textContent = number === item.answer ? '正解！' : '正解は' + item.choices[item.answer];
      document.querySelectorAll('#choices button').forEach((b) => { b.disabled = true; });
      document.querySelector('#next').disabled = false;
    });
    document.querySelector('#choices').append(button);
  });
}
document.querySelector('#next').addEventListener('click', () => {
  index = index + 1;
  if (index < questions.length) render();
  else {
    document.querySelector('#question').textContent = '全問終了！';
    document.querySelector('#choices').replaceChildren();
    document.querySelector('#next').disabled = true;
    document.querySelector('#message').textContent = score + ' / ' + questions.length + '問正解';
  }
});
document.querySelector('#reset').addEventListener('click', () => { index = 0; score = 0; document.querySelector('#score').textContent = 0; render(); });
render();

