let score = 0;
let active = -1;
let timer;
let deadline = 0;
let nextMove = 0;
let speed = 800;
const holes = [];
function paint() {
  holes.forEach((button, index) => {
    button.classList.toggle('active', index === active);
    button.textContent = index === active ? 'もぐら' : '穴' + (index + 1);
  });
  document.querySelector('#score').textContent = score;
}
for (let i = 0; i < 9; i = i + 1) {
  const button = document.createElement('button'); button.type = 'button';
  button.addEventListener('click', () => {
    tick();
    if (Date.now() >= deadline || i !== active) return;
    score = score + 1; active = -1; paint();
  });
  holes.push(button); document.querySelector('#holes').append(button);
}
function tick() {
  const now = Date.now();
  const remaining = Math.max(0, Math.ceil((deadline - now) / 1000));
  document.querySelector('#time').textContent = remaining;
  if (remaining === 0) {
    clearInterval(timer); active = -1; paint();
    document.querySelector('#message').textContent = '終了！ ' + score + '点';
  } else if (now >= nextMove) {
    active = Math.floor(Math.random() * holes.length); nextMove = now + speed; paint();
  }
}
document.querySelector('#start').addEventListener('click', () => {
  clearInterval(timer); score = 0; active = -1;
  speed = Number(document.querySelector('#difficulty')?.value || speed);
  deadline = Date.now() + 15000; nextMove = 0;
  document.querySelector('#message').textContent = 'もぐらを探そう！'; tick();
  timer = setInterval(tick, 100);
});
paint();

